    await openCatalogPrayer('יעלה ויבוא');
    if ((await nodes()).some((n) => n.label === 'יעלה ויבא')) bad.push('экран: «יעלה ויבא» при «יעלה ויבוא» в каталоге');
    // Н-2: значения дафа — одна буква с «׳», несколько — с «״».
    await openZmanim();
    const daf = (await nodes()).map((n) => n.label).filter((l) => /דף [א-ת׳״]+$/.test(l));
    for (const d of daf) if (!/דף ([א-ת]׳|[א-ת]+״[א-ת])$/.test(d)) bad.push(`לימוד יומי: «${d}»`);
    // Н-4: заголовок истории.
    await goHome();
