    await driver.waitUntil(async () => (await nodes()).some((n) => n.label.includes('ל״ט')), { timeout: 15000 }).catch(() => {});
    if ((await nodes()).some((n) => n.label.includes('לידיתון'))) bad.push('תהילים ל״ט: «לידיתון [לידותון]»');
    if (!(await nodes()).some((n) => n.label.includes('למנצח לידותון מזמור'))) bad.push('תהילים ל״ט: нет «למנצח לידותון מזמור»');
    console.log(`[KB-56d002bd] ${bad.join(' | ') || 'всё исправлено'}`);
    expect(bad).toEqual([]);
